// PREFILTRO: descarta lo que no vale la pena clasificar y limpia el cuerpo del mail.
// Editá las listas de abajo para ajustar.

const SKIP_LABELS = ['CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL', 'SPAM', 'TRASH', 'DRAFT'];
// Dominios o remitentes que nunca te interesan (substring, minúsculas)
const BLOCKLIST = ['@medium.com', '@substack.com', 'youtube.com', '@facebookmail.com', 'jobalerts-noreply@linkedin.com', 'alert@indeed.com'];
const MAX_CHARS = 2500;

function htmlToText(html) {
  return String(html || '')
    .replace(/<(script|style|head)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h\d)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function limpiarCuerpo(txt) {
  let t = String(txt || '').replace(/\r/g, '');
  // Cortar el hilo citado (respuestas anteriores)
  const cortes = [
    /^On .{5,200} wrote:\s*$/m,
    /^El .{5,200} escribió:\s*$/m,
    /^Em .{5,200} escreveu:\s*$/m,
    /^-{2,}\s*Original Message\s*-{2,}/mi,
    /^-{2,}\s*Mensaje original\s*-{2,}/mi,
    /^(From|De):.*\n(Sent|Enviado|Date|Fecha|Data):/m,
  ];
  for (const re of cortes) {
    const m = t.match(re);
    if (m && m.index > 0) t = t.slice(0, m.index);
  }
  t = t
    .split('\n')
    .filter((l) => !l.trim().startsWith('>'))
    .join('\n')
    .replace(/https?:\/\/\S{60,}/g, '[link]') // links de tracking larguísimos
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim();
  return t.length > MAX_CHARS ? t.slice(0, MAX_CHARS) + ' [...]' : t;
}

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const labels = j.labelIds || [];

  // Enviados por vos, borradores, promos, social
  if (labels.some((l) => SKIP_LABELS.includes(l))) continue;
  if (labels.includes('SENT') && !labels.includes('INBOX')) continue;

  const remitente = (j.from && j.from.value && j.from.value[0]) || {};
  const email = String(remitente.address || '').toLowerCase();
  const nombre = remitente.name || email;

  if (BLOCKLIST.some((b) => email.includes(b))) continue;

  const headers = j.headers || {};
  const masivo = Boolean(headers['list-unsubscribe']) || /precedence:\s*(bulk|list)/i.test(headers['precedence'] || '');

  const cuerpoBase = j.text && String(j.text).trim() ? j.text : htmlToText(j.html);
  const ts = Date.parse(j.date) || Date.now();

  out.push({
    json: {
      message_id: j.id,
      thread_id: j.threadId,
      de_nombre: nombre,
      de_email: email,
      asunto: j.subject || '(sin asunto)',
      ts,
      masivo,
      cuerpo: limpiarCuerpo(cuerpoBase),
    },
    pairedItem: { item: i },
  });
}

return out;

// ARMAR PROMPT: acá ajustás el modelo, tu perfil y cómo se clasifica.
// El modelo solo extrae datos (tema, si pide respuesta). La urgencia la decide el nodo Parsear con reglas fijas.

const MODELO = 'qwen2.5:7b'; // o el que uses en Pepe

const PERFIL = `La persona busca trabajo remoto (contractor o empleado) en Revenue Operations, Sales Ops, Business Ops o automatización, y además tiene un negocio propio de automatización para pymes. Recibe mails en español, inglés y portugués. EDITÁ ESTE TEXTO con tu propio perfil.`;

const SYSTEM = `Analizás un mail que recibió la persona y devolvés SOLO JSON.

PERFIL DE LA PERSONA:
${PERFIL}

CAMPO "tema" (elegí uno):
- "busqueda_laboral": sobre una postulación o un puesto para la persona. Recruiter o empresa que le escribe, entrevista, assessment, oferta, contrato, rechazo, confirmación o actualización de una postulación (Greenhouse, Lever, Ashby, Workable, Workday).
- "cliente_o_lead": alguien que es o podría ser cliente de la persona (su negocio propio o su empleador actual). Un negocio que pregunta por sus servicios, precio, propuesta o reunión, responde a un mail de prospección, o un cliente actual que avisa algo, pide algo o reporta un problema.
- "alerta_empleos": newsletters o listados automáticos de ofertas de trabajo (job alerts, "new jobs this week", "jobs you may like"). No es una postulación de la persona.
- "venta_a_felipe": alguien que le quiere vender un servicio o producto a la persona (agencias de leads, SaaS, cold emails).
- "servicio_que_paga": facturas, cobros, recibos o avisos de cuentas de herramientas que la persona usa (hosting, SaaS, bancos, apps).
- "otro": todo lo demás (marketing, redes, cursos, notificaciones, spam).

CAMPO "pide_respuesta": true si el mail le hace una pregunta a la persona o le pide hacer algo: dar disponibilidad, agendar o confirmar una reunión o entrevista, pasar precio o propuesta, completar un assessment, mandar un documento, aceptar una oferta, resolver un problema. false si solo informa.

CAMPO "resumen": una oración en español, máximo 25 palabras: quién escribe y qué quiere. Solo texto en español, sin JSON.
CAMPO "accion": máximo 6 palabras en español (ej: "Responder con disponibilidad", "Pasar precio y agendar llamada", "Ninguna").

EJEMPLOS:
- "Could you share your availability for a call?" de un recruiter -> tema busqueda_laboral, pide_respuesta true
- "We received your application" de Greenhouse -> tema busqueda_laboral, pide_respuesta false
- "You are invited to complete an assessment before Friday" -> tema busqueda_laboral, pide_respuesta true
- "Hola, ¿cuánto sale el bot y cuándo hablamos?" de un negocio -> tema cliente_o_lead, pide_respuesta true
- "Te aviso que el lunes cerramos" de un cliente -> tema cliente_o_lead, pide_respuesta false
- "15 new remote jobs for you" -> tema alerta_empleos, pide_respuesta false
- "I help agencies book more calls, worth a chat?" -> tema venta_a_felipe, pide_respuesta false`;

const SCHEMA = {
  type: 'object',
  properties: {
    tema: { type: 'string', enum: ['busqueda_laboral', 'cliente_o_lead', 'alerta_empleos', 'venta_a_felipe', 'servicio_que_paga', 'otro'] },
    pide_respuesta: { type: 'boolean' },
    resumen: { type: 'string' },
    accion: { type: 'string' },
  },
  required: ['tema', 'pide_respuesta', 'resumen', 'accion'],
};

return $input.all().map((item, i) => {
  const m = item.json;
  const user = `Remitente: ${m.de_nombre} <${m.de_email}>
Asunto: ${m.asunto}
Envío masivo (tiene link de desuscripción): ${m.masivo ? 'sí' : 'no'}
Cuerpo:
${m.cuerpo}`;

  return {
    json: {
      ...m,
      ollama_request: {
        model: MODELO,
        stream: false,
        format: SCHEMA,
        keep_alive: '15m',
        options: { temperature: 0, num_ctx: 4096 },
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: user },
        ],
      },
    },
    pairedItem: { item: i },
  };
});

// PARSEAR: combina la respuesta del modelo con los datos del mail.
// Si Ollama falla, usa palabras clave para no perder nada importante.

const CUENTA = 'you@example.com'; // para que el link abra la cuenta correcta

// Reglas: qué temas te interesan y cuándo es urgente
const TEMA_A_CATEGORIA = { busqueda_laboral: 'laboral', cliente_o_lead: 'cliente_lead' };
const TEMAS = ['busqueda_laboral', 'cliente_o_lead', 'alerta_empleos', 'venta_a_felipe', 'servicio_que_paga', 'otro'];

const RE_LABORAL = /(interview|entrevista|application|postulaci[oó]n|candidat|recruit|reclut|hiring|vacante|job offer|offer letter|oferta laboral|assessment|next steps|pr[oó]ximos pasos|greenhouse|lever\.co|ashbyhq|workable|smartrecruiters|teamtailor|recruitee|jobvite|bamboohr|myworkday)/i;
const RE_CLIENTE = /(propuesta|proposal|presupuesto|cotizaci[oó]n|quote|pricing|precio|reuni[oó]n|meeting|demo|contrato|interesad|interested|let's talk|hablemos|or[cç]amento)/i;
const RE_URGENTE = /(entrevista|interview|schedule|agendar|calendly|disponibilidad|availability|offer|oferta|urgente|urgent|asap|deadline|plazo)/i;
// Red de seguridad: en búsqueda laboral, estas frases siempre piden acción aunque el modelo diga que no
const RE_ACCION_LABORAL = /(assessment|coding challenge|take-home|invited you to|te invit|schedule your|pick a time|book a time|availability|disponibilidad|agend[aá]|please sign|firm[aá]|docusign|\boffer\b|oferta de trabajo)/i;

function limpiarResumen(txt, asunto) {
  let t = String(txt || '').split(/[\u3000-\u9fff\uac00-\ud7af{`]/)[0].trim(); // corta texto basura del modelo
  if (t.length > 220) t = t.slice(0, 217).trim() + '...';
  return t || asunto;
}

function heuristica(m) {
  const txt = `${m.asunto}\n${m.cuerpo}`;
  let categoria = 'otro';
  if (RE_LABORAL.test(txt)) categoria = 'laboral';
  else if (RE_CLIENTE.test(txt) && !m.masivo) categoria = 'cliente_lead';
  else if (!m.masivo) categoria = 'sin_clasificar';

  let urgencia = 'ninguna';
  if (categoria === 'laboral' || categoria === 'cliente_lead') {
    urgencia = RE_URGENTE.test(txt) ? 'urgente' : 'normal';
  } else if (categoria === 'sin_clasificar') {
    urgencia = 'normal';
  }
  return { categoria, tema: '-', urgencia, resumen: m.asunto, accion: 'Revisar (Ollama no respondió)' };
}

const base = $('Armar prompt').all();
const respuestas = $input.all();

return respuestas.map((r, i) => {
  // Empareja por pairedItem (no por posición); si el linaje se pierde, cae al índice
  const m = (() => { try { return $('Armar prompt').itemMatching(i).json; } catch (e) { return base[i].json; } })();
  let res = null;
  let fuente = 'ollama';

  try {
    const content = r.json && r.json.message && r.json.message.content;
    if (!content) throw new Error('sin respuesta');
    const p = JSON.parse(content);
    if (!TEMAS.includes(p.tema) || typeof p.pide_respuesta !== 'boolean') throw new Error('valores inválidos');
    const categoria = TEMA_A_CATEGORIA[p.tema] || 'otro';
    const pide = p.pide_respuesta || (categoria === 'laboral' && RE_ACCION_LABORAL.test(`${m.asunto}\n${m.cuerpo}`));
    res = {
      categoria,
      tema: p.tema,
      urgencia: categoria === 'otro' ? 'ninguna' : pide ? 'urgente' : 'normal',
      resumen: limpiarResumen(p.resumen, m.asunto),
      accion: String(p.accion || '').trim() || 'Ninguna',
    };
  } catch (e) {
    res = heuristica(m);
    fuente = 'heuristica';
  }

  // Coherencia entre categoría y urgencia
  if (res.categoria === 'otro') res.urgencia = 'ninguna';
  if (res.categoria !== 'otro' && res.urgencia === 'ninguna') res.urgencia = 'normal';
  if (res.urgencia === 'urgente' && /^ninguna$/i.test(res.accion)) res.accion = 'Revisar y responder';

  const fecha = new Date(m.ts).toLocaleString('es-AR', {
    timeZone: 'America/Argentina/Buenos_Aires',
    day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  });

  return {
    json: {
      fecha,
      ts: m.ts,
      categoria: res.categoria,
      urgencia: res.urgencia,
      tema: res.tema,
      de: m.de_nombre,
      email: m.de_email,
      asunto: m.asunto,
      resumen: res.resumen,
      accion: res.accion,
      fuente,
      link: `https://mail.google.com/mail/?authuser=${encodeURIComponent(CUENTA)}#all/${m.message_id}`,
      message_id: m.message_id,
    },
    pairedItem: { item: i },
  };
});

// AVISO URGENTE: arma el mensaje de Telegram (HTML) para cada mail urgente.

const ETIQUETA = { laboral: 'Búsqueda laboral', cliente_lead: 'Cliente / lead', sin_clasificar: 'Sin clasificar' };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return $input.all().map((item, i) => {
  const m = item.json;
  const lineas = [
    `<b>MAIL URGENTE · ${esc(ETIQUETA[m.categoria] || m.categoria)}</b>`,
    '',
    `<b>De:</b> ${esc(m.de)} (${esc(m.email)})`,
    `<b>Asunto:</b> ${esc(m.asunto)}`,
    '',
    esc(m.resumen),
    '',
    `<b>Acción:</b> ${esc(m.accion)}`,
    `<a href="${esc(m.link)}">Abrir en Gmail</a>`,
  ];
  return { json: { mensaje: lineas.join('\n') }, pairedItem: { item: i } };
});
